            if (fbio == NULL) {
                BIO_printf(bio_err, "Unable to create BIO\n");
                goto shut;
            }
            BIO_push(fbio, sbio);
            /* wait for multi-line response to end from FTP */
            do {
                mbuf_len = BIO_gets(fbio, mbuf, BUFSIZZ);
